var levelOrder = function(root) {
    if (!root) return [];
    const res = [];
    let level = [root];
    while (level.length > 0) {
        res.push(level.map(n => n.val));
        const nextLevel = [];
        for (const node of level) {
            if (node.left) nextLevel.push(node.left);
            if (node.right) nextLevel.push(node.right);
        }
        level = nextLevel;
    }
    return res;
};
